import "/vendor/stasis/stdlib/graphics.stasis";

const SCREEN_W: f32 = 640.0;
const SCREEN_H: f32 = 360.0;
const BRICK_COUNT: i32 = 35;
const BRICK_W: f32 = 78.0;
const BRICK_H: f32 = 22.0;
const PADDLE_W: f32 = 96.0;
const PADDLE_H: f32 = 14.0;
const BALL_SIZE: f32 = 12.0;
const PADDLE_Y: f32 = 326.0;
const ASSET_TOTAL: i32 = 4;

struct Brick {
    x: f32;
    y: f32;
    alive: bool;
}

struct Assets {
    background: Sprite;
    brick: Sprite;
    paddle: Sprite;
    ball: Sprite;
}

struct AssetLoader {
    current: ImageAsset;
    step: i32;
    assets_ready: bool;
    failed: bool;
}

global bricks: Brick[35];
global assets: Assets;
global loader: AssetLoader;
global paddle_x: f32;
global ball_x: f32;
global ball_y: f32;
global ball_vx: f32;
global ball_vy: f32;
global bricks_left: i32;
global ball_active: bool;
global round_done: bool;
global presentation_variant: i32;
global asset_breakout_host_frame: HostFrame;

function loading_completed_count(step: i32): i32 {
    if (step < 0) {
        return 0;
    }
    if (step > ASSET_TOTAL) {
        return ASSET_TOTAL;
    }
    return step;
}

function loading_percent(step: i32): i32 {
    return loading_completed_count(step) * 100 / ASSET_TOTAL;
}

function loading_is_blocking(): bool {
    return !loader.assets_ready && !loader.failed;
}

function clamp_paddle(value: f32): f32 {
    if (value < 0.0) {
        return 0.0;
    }
    if (value > SCREEN_W - PADDLE_W) {
        return SCREEN_W - PADDLE_W;
    }
    return value;
}

function set_paddle_x(value: f32): void {
    paddle_x = clamp_paddle(value);
}

function initialize_bricks(): void {
    foreach (let brick, i in bricks) {
        let column: i32 = i % 7;
        let row: i32 = i / 7;
        brick.x = 25.0 + i32_to_f32(column) * 82.0;
        brick.y = 36.0 + i32_to_f32(row) * 28.0;
        brick.alive = true;
    }
    bricks_left = BRICK_COUNT;
}

function reset_round(): void {
    initialize_bricks();
    paddle_x =(SCREEN_W - PADDLE_W) / 2.0;
    ball_x = SCREEN_W / 2.0 - BALL_SIZE / 2.0;
    ball_y = PADDLE_Y - BALL_SIZE - 2.0;
    ball_vx = 2.2;
    ball_vy = -2.6;
    ball_active = false;
    round_done = false;
}

function update_pointer(): void {
    if (asset_breakout_host_frame.pointer_count > 0) {
        let pointer_x: f32 = asset_breakout_host_frame.pointers[0].x_logical;
        set_paddle_x(pointer_x - PADDLE_W / 2.0);
        if (asset_breakout_host_frame.pointers[0].went_down) {
            if (round_done) {
                reset_round();
            }
            ball_active = true;
        }
    }
    if (asset_breakout_host_frame.keys[80] != 0) {
        set_paddle_x(paddle_x - 4.0);
    }
    if (asset_breakout_host_frame.keys[79] != 0) {
        set_paddle_x(paddle_x + 4.0);
    }
    if (asset_breakout_host_frame.keys[44] != 0) {
        if (round_done) {
            reset_round();
        }
        ball_active = true;
    }
}

function update_ball(): void {
    if (!ball_active) {
        ball_x = paddle_x + PADDLE_W / 2.0 - BALL_SIZE / 2.0;
        ball_y = PADDLE_Y - BALL_SIZE - 2.0;
        return;
    }

    ball_x += ball_vx;
    ball_y += ball_vy;
    if (ball_x < 0.0) {
        ball_x = 0.0;
        ball_vx = 0.0 - ball_vx;
    }
    if (ball_x + BALL_SIZE > SCREEN_W) {
        ball_x = SCREEN_W - BALL_SIZE;
        ball_vx = 0.0 - ball_vx;
    }
    if (ball_y < 0.0) {
        ball_y = 0.0;
        ball_vy = 0.0 - ball_vy;
    }

    let hit_brick: bool = false;
    foreach (let brick, i in bricks) {
        if (
            !hit_brick
            && brick.alive
            && ball_x + BALL_SIZE >= brick.x
            && ball_x <= brick.x + BRICK_W
            && ball_y + BALL_SIZE >= brick.y
            && ball_y <= brick.y + BRICK_H
        ) {
            brick.alive = false;
            bricks_left -= 1;
            ball_vy = 0.0 - ball_vy;
            hit_brick = true;
        }
    }
    if (bricks_left == 0) {
        ball_active = false;
        round_done = true;
        return;
    }

    if (ball_vy > 0.0 && ball_y + BALL_SIZE >= PADDLE_Y && ball_y <= PADDLE_Y + PADDLE_H && ball_x + BALL_SIZE >= paddle_x && ball_x <= paddle_x + PADDLE_W) {
        ball_y = PADDLE_Y - BALL_SIZE;
        ball_vy = 0.0 - ball_vy;
        ball_vx =(ball_x + BALL_SIZE / 2.0 -(paddle_x + PADDLE_W / 2.0)) * 0.06;
        if (ball_vx > 3.4) {
            ball_vx = 3.4;
        }
        if (ball_vx < -3.4) {
            ball_vx = -3.4;
        }
    }
    if (ball_y > SCREEN_H) {
        ball_active = false;
        round_done = true;
    }
}

function request_current_asset(): void {
    if (loader.step == 0) {
        loader.current.load_image("assets/arena_background.png", 640, 360);
    } else if (loader.step == 1) {
        loader.current.load_image("assets/brick.svg", 78, 22);
    } else if (loader.step == 2) {
        loader.current.load_image("assets/paddle.svg", 96, 14);
    } else if (loader.step == 3) {
        loader.current.load_image("assets/ball.svg", 12, 12);
    }
}

function publish_current_asset(): bool {
    if (loader.step == 0) {
        return loader.current.publish(assets.background);
    }
    if (loader.step == 1) {
        return loader.current.publish(assets.brick);
    }
    if (loader.step == 2) {
        return loader.current.publish(assets.paddle);
    }
    return loader.current.publish(assets.ball);
}

function poll_asset_loading(): void {
    if (loader.assets_ready || loader.failed) {
        return;
    }
    if (loader.step >= ASSET_TOTAL) {
        loader.assets_ready = assets.background.valid() && assets.brick.valid() && assets.paddle.valid() && assets.ball.valid();
        if (loader.assets_ready) {
            reset_round();
        } else {
            loader.failed = true;
        }
        return;
    }
    if (loader.current.state == AssetState.None) {
        request_current_asset();
        if (loader.current.state == AssetState.Failed) {
            loader.failed = true;
        }
        return;
    }
    if (loader.current.failed()) {
        loader.failed = true;
        return;
    }
    if (loader.current.ready()) {
        if (!publish_current_asset()) {
            loader.failed = true;
            return;
        }
        loader.step += 1;
    }
}

function main(): i32 {
    if (!init_window(640, 360, "Neon Breakout")) {
        return 1;
    }
    loader.step = 0;
    loader.assets_ready = false;
    loader.failed = false;
    presentation_variant = 0;
    return 0;
}

function tick(): i32 {
    asset_breakout_host_frame.refresh();
    if (asset_breakout_host_frame.quit_requested) {
        return 1;
    }
    poll_asset_loading();
    if (loading_is_blocking()) {
        return 0;
    }
    if (loader.failed) {
        return 0;
    }
    update_pointer();
    update_ball();
    return 0;
}

function render(): i32 {
    begin_frame();
    clear(0.02, 0.02, 0.08, 1.0);
    if (loader.failed) {
        fill_rect(96.0, 140.0, 448.0, 5.0, 0.45, 0.10, 0.16, 1.0);
        fill_rect(96.0, 140.0, 448.0, 5.0, 0.95, 0.30, 0.35, 1.0);
        fill_rect(220.0, 180.0, 200.0, 8.0, 0.95, 0.30, 0.35, 1.0);
        end_frame();
        return 0;
    }
    if (!loader.assets_ready) {
        let progress_width: f32 = 448.0 * i32_to_f32(loading_percent(loader.step)) / 100.0;
        fill_rect(96.0, 140.0, 448.0, 5.0, 0.10, 0.18, 0.30, 1.0);
        fill_rect(96.0, 140.0, progress_width, 5.0, 0.20, 0.85, 0.98, 1.0);
        fill_rect(220.0, 180.0, 200.0, 8.0, 0.10, 0.18, 0.30, 1.0);
        fill_rect(220.0, 180.0, 2.0 * i32_to_f32(loading_percent(loader.step)), 8.0, 0.20, 0.85, 0.98, 1.0);
        end_frame();
        return 0;
    }
    assets.background.draw(0.0, 0.0, 235, 0);
    foreach (let brick, i in bricks) {
        if (brick.alive) {
            assets.brick.draw(brick.x, brick.y, 255, 0);
        }
    }
    assets.paddle.draw(paddle_x, PADDLE_Y, 255, 0);
    assets.ball.draw(ball_x, ball_y, 255, 0);
    if (presentation_variant == 1) {
        fill_rect(0.0, 0.0, SCREEN_W, 2.0, 0.35, 0.85, 1.0, 1.0);
    }
    end_frame();
    return 0;
}

// Compatible swaps preserve the active round and only change a visible accent.
function on_code_swap(): void {
    if (presentation_variant == 0) {
        presentation_variant = 1;
    } else {
        presentation_variant = 0;
    }
}

