const BALL_SIZE: f32 = 12.0;
const PADDLE_Y: f32 = 326.0;
const ASSET_TOTAL: i32 = 4;

struct Brick {
    x: f32;
    y: f32;
    alive: bool;
}

struct Assets {
    background: Sprite;
    brick: Sprite;
    paddle: Sprite;
    ball: Sprite;
}

struct AssetLoader {
    current: ImageAsset;
    step: i32;
    assets_ready: bool;
    failed: bool;
}

global bricks: Brick[35];
global assets: Assets;
global loader: AssetLoader;
global paddle_x: f32;
global ball_x: f32;
global ball_y: f32;
global ball_vx: f32;
global ball_vy: f32;
global bricks_left: i32;
global ball_active: bool;
global round_done: bool;
global presentation_variant: i32;
global asset_breakout_host_frame: HostFrame;

function loading_completed_count(step: i32): i32 {
    if (step < 0) {
        return 0;
    }
    if (step > ASSET_TOTAL) {
        return ASSET_TOTAL;
    }
    return step;
}

function loading_percent(step: i32): i32 {
    return loading_completed_count(step) * 100 / ASSET_TOTAL;
}

function loading_is_blocking(): bool {
    return !loader.assets_ready && !loader.failed;
}

function clamp_paddle(value: f32): f32 {
    if (value < 0.0) {
        return 0.0;
    }
    if (value > SCREEN_W - PADDLE_W) {
        return SCREEN_W - PADDLE_W;
    }
    return value;
}

function set_paddle_x(value: f32): void {
    paddle_x = clamp_paddle(value);
}

function initialize_bricks(): void {
    foreach (let brick, i in bricks) {
        let column: i32 = i % 7;
        let row: i32 = i / 7;
        brick.x = 25.0 + i32_to_f32(column) * 82.0;
        brick.y = 36.0 + i32_to_f32(row) * 28.0;
        brick.alive = true;
    }
    bricks_left = BRICK_COUNT;
}

function reset_round(): void {
    initialize_bricks();
    paddle_x =(SCREEN_W - PADDLE_W) / 2.0;
    ball_x = SCREEN_W / 2.0 - BALL_SIZE / 2.0;
    ball_y = PADDLE_Y - BALL_SIZE - 2.0;
    ball_vx = 2.2;
    ball_vy = -2.6;
    ball_active = false;
    round_done = false;
}

function update_pointer(): void {
    if (asset_breakout_host_frame.pointer_count > 0) {
        let pointer_x: f32 = asset_breakout_host_frame.pointers[0].x_logical;
        set_paddle_x(pointer_x - PADDLE_W / 2.0);
        if (asset_breakout_host_frame.pointers[0].went_down) {
            if (round_done) {
                reset_round();
            }
            ball_active = true;
        }
    }
    if (asset_breakout_host_frame.keys[80] != 0) {
        set_paddle_x(paddle_x - 4.0);
    }
    if (asset_breakout_host_frame.keys[79] != 0) {
        set_paddle_x(paddle_x + 4.0);
    }
    if (asset_breakout_host_frame.keys[44] != 0) {
        if (round_done) {
            reset_round();
        }
        ball_active = true;
    }
}

function update_ball(): void {
    if (!ball_active) {
        ball_x = paddle_x + PADDLE_W / 2.0 - BALL_SIZE / 2.0;
        ball_y = PADDLE_Y - BALL_SIZE - 2.0;
        return;
    }

    ball_x += ball_vx;
    ball_y += ball_vy;
    if (ball_x < 0.0) {
        ball_x = 0.0;
        ball_vx = 0.0 - ball_vx;
    }
    if (ball_x + BALL_SIZE > SCREEN_W) {
        ball_x = SCREEN_W - BALL_SIZE;
        ball_vx = 0.0 - ball_vx;
    }
    if (ball_y < 0.0) {
        ball_y = 0.0;
        ball_vy = 0.0 - ball_vy;
    }

    let hit_brick: bool = false;
    foreach (let brick, i in bricks) {
        if (
            !hit_brick
            && brick.alive
            && ball_x + BALL_SIZE >= brick.x
            && ball_x <= brick.x + BRICK_W
            && ball_y + BALL_SIZE >= brick.y
            && ball_y <= brick.y + BRICK_H
        ) {
            brick.alive = false;
            bricks_left -= 1;
            ball_vy = 0.0 - ball_vy;
            hit_brick = true;
        }
    }
    if (bricks_left == 0) {
        ball_active = false;
        round_done = true;
        return;
    }

