        ball_y = PADDLE_Y - BALL_SIZE;
        ball_vy = 0.0 - ball_vy;
        ball_vx =(ball_x + BALL_SIZE / 2.0 -(paddle_x + PADDLE_W / 2.0)) * 0.06;
        if (ball_vx > 3.4) {
            ball_vx = 3.4;
        }
        if (ball_vx < -3.4) {
            ball_vx = -3.4;
        }
